{
  "name": "grain-trace-computations",
  "version": "1.0.0",
  "description": "Deterministic, parameterized grain-trace queries bound to this sealed World. Call via application/run.py; do not read source to use.",
  "world_binding": {
    "world_id": "v0",
    "revision": 242,
    "world_hash": "dc2e7e45c1327fc997691b4fa4071c5fd44edb6aed2b57e2d1e4e4c70a471eb8",
    "sqlite_sha256": "b2053bcf7c9e02a39b64a77065ff952c4357e494b024292c08eb9a6ff9481a4c",
    "sqlite_path": "world/world.sqlite"
  },
  "invoke": {
    "entrypoint": "application/run.py",
    "usage": "python3 application/run.py <computation_id> --param NAME=VALUE [--param NAME=VALUE ...] [--pretty]",
    "list": "python3 application/run.py --list",
    "params_json": "python3 application/run.py <computation_id> --params-json '{\"dispatch\":\"PGE-OUT-5001\"}'"
  },
  "computations": [
    {
      "id": "shipment_source_status",
      "family": "shipment_source_status",
      "manifest": "manifests/shipment_source_status.json",
      "parameters": ["dispatch"]
    },
    {
      "id": "processor_receipt_provenance",
      "family": "processor_receipt_provenance",
      "manifest": "manifests/processor_receipt_provenance.json",
      "parameters": ["processor_receipt"]
    },
    {
      "id": "custody_owner_at",
      "family": "custody_owner_at",
      "manifest": "manifests/custody_owner_at.json",
      "parameters": ["material", "timestamp"]
    },
    {
      "id": "inspection_downstream_scope",
      "family": "inspection_downstream_scope",
      "manifest": "manifests/inspection_downstream_scope.json",
      "parameters": ["sample"]
    }
  ]
}

{
  "id": "processor_receipt_provenance",
  "family": "processor_receipt_provenance",
  "title": "Processor receipt provenance",
  "description": "For a mill receiving slip, summarize the established upstream dispatch/material path, any processing output, and unresolved links (missing allocation, missing mill receipt elsewhere, unexplained quantity differences).",
  "parameters": [
    {
      "name": "processor_receipt",
      "type": "string",
      "required": true,
      "description": "Processor/mill receipt token (e.g. HFM-IN-601)."
    }
  ],
  "output": {
    "type": "object",
    "required": [
      "computation",
      "world_binding",
      "query",
      "receipt",
      "upstream",
      "processing",
      "unresolved"
    ]
  }
}

{
  "id": "custody_owner_at",
  "family": "custody_owner_at",
  "title": "Custody and owner at timestamp",
  "description": "At an instant, return the recorded owner and custodian (holder) of a material identity from covering ownership events. Empty owner_after is not treated as an established owner.",
  "parameters": [
    {
      "name": "material",
      "type": "string",
      "required": true,
      "description": "Material, ticket, or ownership scope token (e.g. DR-44)."
    },
    {
      "name": "timestamp",
      "type": "string",
      "required": true,
      "description": "ISO-8601 timestamp with offset (e.g. 2025-09-03T12:00:00-05:00)."
    }
  ],
  "output": {
    "type": "object",
    "required": [
      "computation",
      "world_binding",
      "query",
      "material",
      "owner",
      "custodian",
      "covering_events",
      "unresolved"
    ]
  }
}

{
  "id": "inspection_downstream_scope",
  "family": "inspection_downstream_scope",
  "title": "Inspection downstream scope",
  "description": "From a lab sample, report established downstream shipment, processor receipt, and processed output when World evidence links them. Preserve unresolved ticket identity and unallocated bin blends.",
  "parameters": [
    {
      "name": "sample",
      "type": "string",
      "required": true,
      "description": "Lab sample token (e.g. SMP-7714A)."
    }
  ],
  "output": {
    "type": "object",
    "required": [
      "computation",
      "world_binding",
      "query",
      "sample",
      "established_source_ticket",
      "established_downstream",
      "unresolved"
    ]
  }
}

